package co.agenda.alex;
import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.JavascriptInterface;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import android.webkit.WebResourceRequest;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class MainActivity extends Activity {
 WebView web; String pendingExport;
 android.speech.SpeechRecognizer recognizer; boolean listening=false;
 void destroyRecognizer(){listening=false;if(recognizer!=null){try{recognizer.cancel();recognizer.destroy();}catch(Exception ignored){}recognizer=null;}}
 void startVoice(){
  destroyRecognizer();
  if(!android.speech.SpeechRecognizer.isRecognitionAvailable(this)){callback("vozError","No se encontró un servicio de reconocimiento de voz en el dispositivo.");return;}
  try{listening=true;recognizer=android.speech.SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(new android.speech.RecognitionListener(){
   public void onReadyForSpeech(Bundle p){if(listening)callback("vozEstado","Te escucho…");}
   public void onBeginningOfSpeech(){if(listening)callback("vozEstado","Te escucho…");}
   public void onRmsChanged(float v){} public void onBufferReceived(byte[] b){}
   public void onEndOfSpeech(){if(listening)callback("vozEstado","Procesando lo que dijiste…");}
   public void onError(int e){if(!listening)return;destroyRecognizer();String msg=e==android.speech.SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS?"Permite el micrófono para dictar.":e==android.speech.SpeechRecognizer.ERROR_NO_MATCH||e==android.speech.SpeechRecognizer.ERROR_SPEECH_TIMEOUT?"No pude entenderte. Toca ‘Intentar de nuevo’.":e==android.speech.SpeechRecognizer.ERROR_NETWORK||e==android.speech.SpeechRecognizer.ERROR_NETWORK_TIMEOUT?"El servicio de voz no pudo conectarse. Inténtalo de nuevo.":"No pude usar el reconocimiento de voz. Inténtalo de nuevo.";callback("vozError",msg);}
   public void onResults(Bundle r){if(!listening)return;java.util.ArrayList<String> a=r==null?null:r.getStringArrayList(android.speech.SpeechRecognizer.RESULTS_RECOGNITION);String text=a==null||a.isEmpty()?"":a.get(0);destroyRecognizer();if(text.isEmpty())callback("vozError","No pude entenderte. Toca ‘Intentar de nuevo’.");else callback("recibirDictado",text);}
   public void onPartialResults(Bundle r){if(!listening)return;java.util.ArrayList<String> a=r==null?null:r.getStringArrayList(android.speech.SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null&&!a.isEmpty())callback("vozParcial",a.get(0));}
   public void onEvent(int n,Bundle b){}
  });Intent i=new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE,"es-CO");i.putExtra(android.speech.RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);recognizer.startListening(i);callback("vozEstado","Preparando el micrófono…");}
  catch(Exception e){destroyRecognizer();callback("vozError","No se pudo iniciar el reconocimiento. Inténtalo de nuevo.");}
 }
 String notificationState(){try{if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return "sin_permiso";android.app.NotificationManager nm=(android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(android.os.Build.VERSION.SDK_INT>=24&&!nm.areNotificationsEnabled())return "desactivado";if(android.os.Build.VERSION.SDK_INT>=26){android.app.NotificationChannel ch=nm.getNotificationChannel("agenda_reminders");if(ch!=null&&ch.getImportance()==android.app.NotificationManager.IMPORTANCE_NONE)return "desactivado";}return "activo";}catch(Exception e){return "desconocido";}}
 @Override protected void onResume(){super.onResume();if(web!=null)callback("actualizarEstadoNotificaciones",notificationState());}
 @Override protected void onDestroy(){destroyRecognizer();super.onDestroy();}
 @Override public void onCreate(Bundle b){super.onCreate(b);android.widget.FrameLayout root=new android.widget.FrameLayout(this);root.setBackgroundColor(android.graphics.Color.rgb(16,17,16));web=new WebView(this);web.setBackgroundColor(android.graphics.Color.rgb(16,17,16));root.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));if(android.os.Build.VERSION.SDK_INT>=35){root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets safe=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());v.setPadding(safe.left,safe.top,safe.right,safe.bottom);return insets;});}web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(false);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.addJavascriptInterface(new Bridge(),"AgendaAndroid");web.setWebChromeClient(new android.webkit.WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return !r.getUrl().toString().equals("file:///android_asset/index.html");}});setContentView(root);root.requestApplyInsets();web.loadUrl("file:///android_asset/index.html");}
 void callback(String name,String value){web.evaluateJavascript("window."+name+" && window."+name+"("+org.json.JSONObject.quote(value)+")",null);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK || data==null){if(request==212)pendingExport=null;return;}if(request==211){java.util.ArrayList<String> matches=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(matches!=null&&!matches.isEmpty())callback("recibirDictado",matches.get(0));return;}Uri uri=data.getData();if(uri==null)return;try{if(request==212){if(pendingExport==null)throw new IOException("La exportación se interrumpió; vuelve a intentarlo");try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No se pudo abrir el destino");out.write(pendingExport.getBytes(StandardCharsets.UTF_8));out.flush();}pendingExport=null;callback("resultadoCopia","Copia guardada. Consérvala en un lugar seguro: contiene tus datos sin cifrar.");}else if(request==213){try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream buf=new ByteArrayOutputStream()){if(in==null)throw new IOException("No se pudo abrir el archivo");byte[] chunk=new byte[8192];int n,total=0;while((n=in.read(chunk))!=-1){total+=n;if(total>4*1024*1024)throw new IOException("Archivo demasiado grande (máximo 4 MB)");buf.write(chunk,0,n);}callback("recibirCopia",buf.toString("UTF-8"));}}}catch(Exception e){pendingExport=null;callback("resultadoCopia","No se pudo completar la operación: "+e.getMessage());}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==215){if(grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)startVoice();else callback("vozError","Necesito permiso para usar el micrófono. También puedes escribir el texto.");return;}if(request==214)callback("actualizarEstadoNotificaciones",notificationState());}
 public class Bridge {
 @JavascriptInterface public void dictar(){runOnUiThread(()->{if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){callback("vozEstado","Esperando permiso del micrófono…");requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},215);}else startVoice();});}
 @JavascriptInterface public void detenerDictado(){runOnUiThread(()->{if(listening&&recognizer!=null){try{recognizer.stopListening();callback("vozEstado","Procesando lo que dijiste…");}catch(Exception e){destroyRecognizer();callback("vozError","No se pudo terminar el dictado. Inténtalo de nuevo.");}}});}
 @JavascriptInterface public void cancelarDictado(){runOnUiThread(()->destroyRecognizer());}
 @JavascriptInterface public void consultarNotificaciones(){runOnUiThread(()->callback("actualizarEstadoNotificaciones",notificationState()));}
 @JavascriptInterface public void permisos(){runOnUiThread(()->{if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},214);}else {try{Intent i=new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS);i.putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}catch(Exception e){callback("estadoRecordatorios","Revisa las notificaciones en Ajustes de la app.");}}});}
 @JavascriptInterface public void sincronizar(String data){try{ReminderManager.sync(MainActivity.this,data);}catch(Exception e){runOnUiThread(()->callback("estadoRecordatorios","No se pudieron programar los recordatorios. Abre la app y vuelve a intentarlo."));}}
 @JavascriptInterface public void exportar(String data){if(data==null||data.length()>4*1024*1024){runOnUiThread(()->callback("resultadoCopia","La copia supera el límite de 4 MB."));return;}runOnUiThread(()->{try{pendingExport=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"mi-agenda-copia.json");startActivityForResult(i,212);}catch(Exception e){pendingExport=null;callback("resultadoCopia","No hay selector de archivos disponible.");}});}
 @JavascriptInterface public void importar(){runOnUiThread(()->{try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,213);}catch(Exception e){callback("resultadoCopia","No hay selector de archivos disponible.");}});}

 }
}
